#!/usr/bin/env python3
# @spec [Doc-05A_V1.0, §6 / §12 / §12.4a] | @implemented [2026-06-10]
# plain English: the INDEPENDENT Python reference implementation of the V1.0 mastery
#   formula, and the canonical encoding of the 31 stress-test fixtures (B1-B23, S1-S8)
#   from Doc 05A §12. Per Doc 05A §12.4a (RB-05A-V1-13 / MED3) the expected fixture
#   values MUST be generated by an independent Python reference, NOT by the SQL function
#   in §6. This file IS that reference. The PL/pgSQL `compute_mastery_for_entity` is then
#   required to match this reference bit-for-bit within the §12.4 tolerances.
#
#   This file intentionally hard-codes the LOCKED constants from Doc 05 Parent §10.1.
#   That is by design (§12.4a: "Reads only the locked constants from Parent §10.1, no DB
#   dependency"): the reference must be an INDEPENDENT source of truth that does not read
#   the DB-seeded `mastery_constants`. The no-hardcoded-constants CI guard therefore
#   excludes scripts/reference/ (it gates engine/service code, not the reference oracle).
#
# expected outcome: `--selfcheck` recomputes all 31 fixtures and asserts they equal the
#   §12-published expected values (proving the reference matches the spec table);
#   `--emit-json PATH` writes the fixtures + reference outputs for the SQL parity harness.
# trade-offs: float64 position weights (§12.4a mandates `0.5 ** ((pos-1)/30)`); the SQL
#   side uses numeric POWER — agreement is within the §12.4 tolerances (acc ±1e-6,
#   score ±1e-4, pct ±0.01, level exact), which the three-way comparator enforces.
# edge cases: cold-start (0 events) and below-threshold (<5) return NULL per §6 Step 3;
#   easy-cap via min(1.0, ...); macro-average renormalizes over PRESENT sources only.

from __future__ import annotations

import argparse
import json
import sys
from decimal import Decimal, ROUND_HALF_UP
from typing import Optional, TypedDict

# ---------------------------------------------------------------------------
# Locked constants — Doc 05 Parent §10.1 (V1.0). Mirrors the DB-seeded
# mastery_constants in supabase/migrations/20260610010000_ws3_mastery_formula.sql.
# The reference is an INDEPENDENT oracle, so it carries the locked values directly.
# ---------------------------------------------------------------------------
POSITION_HALF_LIFE = 30.0
MIN_EVENTS_FOR_MASTERY = 5
WEIGHT_SOURCE = {"test": 0.50, "practice": 0.30, "review": 0.20}
DIFFICULTY_WEIGHT = {1: 0.79, 2: 1.0, 3: 1.20}  # 1=easy, 2=medium, 3=hard
MASTERY_MIN = 0.0
MASTERY_MAX = 1.0
LEVEL_BOUNDARIES = (0.20, 0.40, 0.60, 0.80)  # L1_min, L2_min, L3_min, L4_min
ROUND_SCORE_DECIMALS = 4
ROUND_PCT_DECIMALS = 2
ROUND_ACC_DECIMALS = 6

_DIFF_LETTER = {"E": 1, "M": 2, "H": 3}


class Event(TypedDict):
    source_family: str  # 'test' | 'practice' | 'review'
    difficulty: int     # 1 | 2 | 3
    correct: bool


class MasteryResult(TypedDict):
    total_events: int
    acc_test: Optional[float]
    acc_practice: Optional[float]
    acc_review: Optional[float]
    mastery_score: Optional[float]
    mastery_pct: Optional[float]
    mastery_level: Optional[int]


def _round_half_up(value: float, decimals: int) -> float:
    """Round-half-away-from-zero to `decimals`, matching PostgreSQL ROUND(numeric, n).
    All formula values are non-negative, so HALF_UP == round-half-away-from-zero here."""
    q = Decimal(1).scaleb(-decimals)  # 10**-decimals
    return float(Decimal(repr(value)).quantize(q, rounding=ROUND_HALF_UP))


def _lookup_level(score: float) -> int:
    # Doc 05A §6.3 half-open intervals: each level covers [min, next_min).
    l1, l2, l3, l4 = LEVEL_BOUNDARIES
    if score < l1:
        return 0
    if score < l2:
        return 1
    if score < l3:
        return 2
    if score < l4:
        return 3
    return 4


def compute_mastery(events: list[Event]) -> MasteryResult:
    """Doc 05A §6 formula, independent reference.

    Positions are assigned GLOBALLY over all the entity's events by recency
    (most-recent = position 1), exactly as the SQL ROW_NUMBER() OVER (ORDER BY
    occurred_at DESC, event_id DESC). The caller supplies `events` already in
    recency order (index 0 = most recent). acc_source is offset-invariant for a
    source occupying a contiguous position block (the §12 fixtures are authored
    that way), so per-source positions coincide with the global ones.
    """
    total = len(events)

    # Step 3 (early): cold-start / below-threshold → NULL.
    if total < MIN_EVENTS_FOR_MASTERY:
        return MasteryResult(
            total_events=total, acc_test=None, acc_practice=None, acc_review=None,
            mastery_score=None, mastery_pct=None, mastery_level=None,
        )

    # Step 2: global position (1-based), position weight, per-source weighted accuracy.
    num: dict[str, float] = {}
    den: dict[str, float] = {}
    for idx, ev in enumerate(events):
        pos = idx + 1
        pos_w = 0.5 ** ((pos - 1) / POSITION_HALF_LIFE)
        d_w = DIFFICULTY_WEIGHT[ev["difficulty"]]
        src = ev["source_family"]
        num[src] = num.get(src, 0.0) + d_w * pos_w * (1 if ev["correct"] else 0)
        den[src] = den.get(src, 0.0) + pos_w

    def acc(src: str) -> Optional[float]:
        if src not in den or den[src] == 0:
            return None
        return min(1.0, num[src] / den[src])

    acc_test = acc("test")
    acc_practice = acc("practice")
    acc_review = acc("review")

    # Step 4: macro-average across PRESENT sources, renormalized.
    weighted_sum = 0.0
    weight_sum = 0.0
    for src, a in (("test", acc_test), ("practice", acc_practice), ("review", acc_review)):
        if a is not None:
            weighted_sum += WEIGHT_SOURCE[src] * a
            weight_sum += WEIGHT_SOURCE[src]
    raw = weighted_sum / weight_sum  # weight_sum > 0 since total >= 5 implies a source present

    # Step 5: clamp + round; pct from rounded score; level from rounded score.
    score = _round_half_up(min(MASTERY_MAX, max(MASTERY_MIN, raw)), ROUND_SCORE_DECIMALS)
    pct = _round_half_up(100.0 * score, ROUND_PCT_DECIMALS)
    level = _lookup_level(score)

    # Step 6: round per-source accuracies for storage/report.
    return MasteryResult(
        total_events=total,
        acc_test=None if acc_test is None else _round_half_up(acc_test, ROUND_ACC_DECIMALS),
        acc_practice=None if acc_practice is None else _round_half_up(acc_practice, ROUND_ACC_DECIMALS),
        acc_review=None if acc_review is None else _round_half_up(acc_review, ROUND_ACC_DECIMALS),
        mastery_score=score,
        mastery_pct=pct,
        mastery_level=level,
    )


# ---------------------------------------------------------------------------
# The 31 canonical fixtures (Doc 05A §12.1 B1-B23 + §12.2 S1-S8).
# Each fixture event list is in RECENCY ORDER (index 0 = most recent = position 1).
# Multi-source fixtures lay each source out as a CONTIGUOUS block (recent-correct
# within the block); acc_source is offset-invariant so block order is immaterial.
# `block(src, letter, correct, n)` expands to n events.
# ---------------------------------------------------------------------------
def _block(src: str, letter: str, correct: bool, n: int) -> list[Event]:
    return [Event(source_family=src, difficulty=_DIFF_LETTER[letter], correct=correct) for _ in range(n)]


def _alternating(n: int) -> list[Event]:
    # B10: (prac,M,✓),(prac,M,✗),… — position 1 correct, 2 wrong, alternating.
    out: list[Event] = []
    for i in range(n):
        out.append(Event(source_family="practice", difficulty=2, correct=(i % 2 == 0)))
    return out


