def _acc_close(a: Optional[float], b: Optional[float], tol: float) -> bool:
    if a is None or b is None:
        return a is None and b is None
    return abs(a - b) <= tol


def _selfcheck() -> int:
    """Recompute each fixture and assert it matches the §12-published expected values.
    Proves: Python reference == Doc 05A §12 table. Tolerances per §12.4."""
    failures: list[str] = []
    for fid, fx in FIXTURES.items():
        got = compute_mastery(fx["events"])
        exp = fx["expected"]
        checks = [
            ("total", got["total_events"] == exp["total"]),
            ("acc_test", _acc_close(got["acc_test"], exp["acc_test"], 1e-6)),
            ("acc_practice", _acc_close(got["acc_practice"], exp["acc_practice"], 1e-6)),
            ("acc_review", _acc_close(got["acc_review"], exp["acc_review"], 1e-6)),
            ("score", _acc_close(got["mastery_score"], exp["score"], 1e-4)),
            ("pct", _acc_close(got["mastery_pct"], exp["pct"], 1e-2)),
            ("level", got["mastery_level"] == exp["level"]),
        ]
        bad = [name for name, ok in checks if not ok]
        if bad:
            failures.append(f"{fid} ({fx['desc']}): mismatched {bad}\n    got={got}\n    exp={exp}")
    if failures:
        print("REFERENCE SELF-CHECK FAILED — Python reference does not match Doc 05A §12:")
        for f in failures:
            print("  - " + f)
        return 1
    print(f"REFERENCE SELF-CHECK PASSED — all {len(FIXTURES)} fixtures match Doc 05A §12 (B1-B23, S1-S8).")
    return 0


def _emit_json(path: str) -> int:
    """Emit fixtures (events in recency order) + reference outputs as JSON for the
    SQL parity harness. The harness loads the SAME event sets into a fixture-backed
    canonical_mastery_events and compares SQL output three-way."""
    out = {}
    for fid, fx in FIXTURES.items():
        got = compute_mastery(fx["events"])
        out[fid] = {
            "desc": fx["desc"],
            "events": fx["events"],   # recency order; index 0 == position 1
            "reference": got,
            "expected": fx["expected"],
        }
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(out, fh, indent=2)
    print(f"wrote {len(out)} fixtures + reference outputs → {path}")
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description="Doc 05A V1.0 mastery formula — Python reference + fixtures")
    ap.add_argument("--selfcheck", action="store_true", help="assert reference == Doc 05A §12 expected")
    ap.add_argument("--emit-json", metavar="PATH", help="write fixtures + reference outputs to PATH")
    args = ap.parse_args()
    if args.emit_json:
        return _emit_json(args.emit_json)
    # default action is the self-check (the CI gate's first half).
    return _selfcheck()


if __name__ == "__main__":
    sys.exit(main())
